# =============================================================================
# IrineCore — Default Build & CLI Configuration Template (conf/dist/config.ps1)
# =============================================================================
# DO NOT EDIT THIS FILE DIRECTLY.
# Copy to `conf\config.ps1` (gitignored) and override only the variables you need.
# Both `.\irine.ps1` and `.\apps\compiler\compile.ps1` dot-source:
#   1. conf\dist\config.ps1  (tracked defaults)
#   2. conf\config.ps1       (optional local user overrides)
# =============================================================================

# CMake build configuration: Release | RelWithDebInfo | Debug
$IRINE_BUILD_TYPE = "Release"

# Build and staged distribution directories (relative to repo root or absolute)
$IRINE_BUILD_DIR        = "build"
$IRINE_DIST_DIR         = "env\dist"
$IRINE_CLIENT_BUILD_DIR = "build-client"

# Module build mode: static | disabled
$IRINE_MODULES = "static"

# Semicolon-separated list of module folder names to skip (e.g. "Player-Bots;examples")
$DISABLED_IRINE_MODULES = ""

# Build auxiliary packaging/patching tools: ON | OFF
$IRINE_BUILD_TOOLS = "ON"

# Client build options (used by `.\irine.ps1 compiler client`): x64 | Win32
$IRINE_CLIENT_ARCH = "x64"
$IRINE_CLIENT_LTO  = $false

# Optional extra CMake configure arguments (string array)
$IRINE_CMAKE_EXTRA_ARGS = @()

# Number of rotated log backups to keep via `.\irine.ps1 server rotate-logs`
$IRINE_LOG_ROTATE_KEEP = 5
